from tcadutils import *
def match_prefix(input_string, string_list):
    string_list=list(set(string_list))
    matches = [s for s in string_list if s.upper().startswith(input_string.upper())]
    np=input_string.count('_')
    matches = [s for s in matches if s.count('_') <= np]
    if len(matches) == 1:
        return matches[0]
    else:
        return False

def getc(tcadcommand,**kwargs):
   for i in kwargs:
        if hasattr(tcadcommand,i):
           method=getattr(tcadcommand,i)
           method.value=kwargs[i]
        elif hasattr(tcadcommand,f"t_{i.upper()}"):
           method=getattr(tcadcommand,f"t_{i.upper()}")
           method.value=kwargs[i]
        elif hasattr(tcadcommand,f"t_{i.replace('.','_').upper()}"):
           method=getattr(tcadcommand,f"t_{i.replace('.','_').upper()}")
           method.value=kwargs[i]
        else:
            a=match_prefix(f"t_{i.upper()}",tcadcommand.parameters)
            if a:
                method=getattr(tcadcommand,a)
                method.value=kwargs[i]
            else:       
                if not hasattr(tcadcommand,"extra_parameters"):
                        tcadcommand.extra_parameters=[]
                if kwargs[i] is True:
                        tcadcommand.extra_parameters.append(f"{i}")
                else:
                        if not isinstance(kwargs[i], (int, float)):
                                tcadcommand.extra_parameters.append(f"{i}={kwargs[i]}")
                        else:
                                tcadcommand.extra_parameters.append(f"{i}={format_number(kwargs[i])}")
   tcadcommand.parameters=list(set(tcadcommand.parameters))
   return tcadcommand


class tcad:
    def __init__(self):
        self.commands={'DEFECTS':'DEFECTS','DEGRADATION':'DEGRADATION','DEVDEGBULKTRAP':'DEVDEGBULKTRAP','DOPING':'DOPING','DOSEXTRACT':'DOSEXTRACT','ELECTRODE':'ELECTRODE','ELIMINATE':'ELIMINATE','EXPORT':'EXPORT','EXTRACT':'EXTRACT','EYE.DIAGRAM':'EYE_DIAGRAM','A.M':'A_M','R.M':"R_M",'X.M':'X_M','Y.M':'Y_M','FDX.M':'FDX_M','FOURIER':'FOURIER','GO':'GO','IMPACT':'IMPACT','INTDEFECTS':'INTDEFECTS','INTERFACE':'INTERFACE','INTTRAP':'INTTRAP','LASER':'LASER','LED':'LED','LENS':'LENS','BEAM':'BEAM','LOAD':'LOAD','LOG':'LOG','LX.M':'LX_M','MATERIAL':'MATERIAL','MEASURE':'MEASURE','MESH':'MESH','METHOD':'METHOD','MOBILITY':'MOBILITY','MODELS':'MODELS','MQW':'MQW','CHARACTERIZE':'CHARACTERIZE','NITRIDECHARGE':'NITRIDECHARGE','ODEFECTS':'ODEFECTS','OINTDEFECTS':'OINTDEFECTS','OPTIONS':'OPTIONS','OUTPUT':'OUTPUT','PHOTOGENERATE':'PHOTOGENERATE','PHOTONICS':'PHOTONICS','PML':'PML','PROBE':'PROBE','QTREGION':'QTREGION','COMM':'COMM','QTX.M':'QTX_M','QUIT':'QUIT','REACTION':'REACTION','REGION':'REGION','REGRID':'REGRID','SAVE':'SAVE','SET':'SET','SINGLEEVENTUPSET':'SINGLEEVENTUPSET','SOLAR':'SOLAR','SOLVE':'SOLVE','CONTACT':'CONTACT','SPX.M':'SPX_M','SYMBOLIC':'SYMBOLIC','SPREAD':'SPREAD','SYSTEM':'SYSTEM','THERMCONTACT':'THERMCONTACT','TITLE':'TITLE','TONYPLOT':'TONYPLOT','TRAP':'TRAP','UTMOST':'UTMOST','VCSEL':'VCSEL','CURVETRACE':'CURVETRACE','WAVEFORM':'WAVEFORM','WAVEGUIDE':'WAVEGUIDE','DATASET':'DATASET','DBR':'DBR',}
        self.commandall=[]



    def get_allcommand(self):
        result=""
        for i in self.commandall:
            if isinstance(i, str):
                result+=i+'\n'
            else:      
                result+=i.get_command()+'\n'
        return result
    def get_allcommandlist(self):
        result=[]
        for i in self.commandall:
            if isinstance(i, str):
                result.append(i+'\n')
            else:      
                result.append(i.get_command()+'\n')
        return result

