class c_DOSEXTRACT (tcadcommand):
    def __init__(self):
        self.commandname='DOSEXTRACT'
        self.t_ACCEPTOR=tcadparameter('ACCEPTOR','Logical','False','')
        self.t_ACCEPTOR.description='''Specifies that acceptor traps are to be extracted.'''
        self.t_ACCEPTOR.description_zh='''指定要提取接受器陷阱。'''
        self.t_CVFILE=tcadparameter('CVFILE','Character','','')
        self.t_CVFILE.description='''Specifies the file name which contains the capacitance/gate voltage data.'''
        self.t_CVFILE.description_zh='''指定包含电容/栅极电压数据的文件名。'''
        self.t_DONOR=tcadparameter('DONOR','Logical','False','')
        self.t_DONOR.description='''Specifies that donor traps are to be extracted.'''
        self.t_DONOR.description_zh='''指定要提取捐赠者陷阱。'''
        self.t_EG300=tcadparameter('EG300','Real','','eV')
        self.t_EG300.description='''Specifies  the  value  of  bandgap  of  the  material.  EMAX  will  be  calculated  from  this
value if it is specified along with EI.'''
        self.t_EG300.description_zh='''指定材料的带隙值。如果同时指定了该值和EI，EMAX将由此计算得出。'''
        self.t_EI=tcadparameter('EI','Real','','eV')
        self.t_EI.description='''Specifies the intrinsic energy level of the material.'''
        self.t_EI.description_zh='''指定材料的固有能级。'''
        self.t_EMAX=tcadparameter('EMAX','Real','','eV')
        self.t_EMAX.description='''Specifies  the  maximum  energy  seperation  from  the  intrinsic  energy  level  (EI)  that
should be calculated.'''
        self.t_EMAX.description_zh='''指定从固有能级（EI）计算的最大能量分离。'''
        self.t_GRAIN_SIZE=tcadparameter('GRAIN.SIZE','Real','','m')
        self.t_GRAIN_SIZE.description='''Specifies the size of the grains.'''
        self.t_GRAIN_SIZE.description_zh='''指定颗粒的大小。'''
        self.t_GRAINFILE=tcadparameter('GRAINFILE','Character','','')
        self.t_GRAINFILE.description='''Specifies the file name where the grain boundary DOS distribution, as a function of
energy, will be stored.'''
        self.t_GRAINFILE.description_zh='''指定文件名，在该文件中将以能量为函数的晶界态密度分布进行存储。'''
        self.t_INTFILE=tcadparameter('INTFILE','Character','','')
        self.t_INTFILE.description='''Specifies the file name where the interface DOS distribution, as a function of energy,
will be stored.'''
        self.t_INTFILE.description_zh='''指定文件名，其中接口DOS分布，作为能量的函数，将被存储。'''
        self.t_IVFILE=tcadparameter('IVFILE','Character','','')
        self.t_IVFILE.description='''Specifies the file name that contains the drain current/gate voltage data.'''
        self.t_IVFILE.description_zh='''指定包含漏极电流/栅极电压数据的文件名。'''
        self.t_LENGTH=tcadparameter('LENGTH','Real','','m')
        self.t_LENGTH.description='''Specifies the x-direction length under the gate.'''
        self.t_LENGTH.description_zh='''指定闸门下x方向长度。'''
        self.t_MIN_DENSITY=tcadparameter('MIN.DENSITY','Real','1','cm-2')
        self.t_MIN_DENSITY.description='''Specifies the minimum trap density to be used for the grain boundary traps.'''
        self.t_MIN_DENSITY.description_zh='''指定用于晶界陷阱的最小陷阱密度。'''
        self.t_MU=tcadparameter('MU','Real','','cm2/Vs')
        self.t_MU.description='''Specifies the majority carrier mobility.'''
        self.t_MU.description_zh='''指定多数载流子的迁移率。'''
        self.t_NUM_DIVISIONS=tcadparameter('NUM.DIVISIONS','Real','25','')
        self.t_NUM_DIVISIONS.description='''Specifies 
the  number  of  divisions  used  from 
the  oxide-silicon 
interface 
to 
the
substrate.'''
        self.t_NUM_DIVISIONS.description_zh='''指定了从氧化物-硅界面到衬底所使用的分段数。'''
        self.t_NUM_GRAINS=tcadparameter('NUM.GRAINS','Real','','')
        self.t_NUM_GRAINS.description='''Specifies the number of grains in the device.'''
        self.t_NUM_GRAINS.description_zh='''指定设备中的谷物数量。'''
        self.t_OUTFILE=tcadparameter('OUTFILE','Character','','')
        self.t_OUTFILE.description='''Specifies the file name where the grain boundary and interface DOS distribution, as a
function of energy, will be stored.'''
        self.t_OUTFILE.description_zh='''指定文件名，用于存储作为能量函数的晶界和界面态密度分布。'''
        self.t_TEMPERATURE=tcadparameter('TEMPERATURE','Real','300','K')
        self.t_TEMPERATURE.description='''Specifies the temperature used in the DOS extraction.'''
        self.t_TEMPERATURE.description_zh='''指定在DOS提取中使用的温度。'''
        self.t_TOX=tcadparameter('TOX','Real','','m')
        self.t_TOX.description='''Specifies the oxide thickness.'''
        self.t_TOX.description_zh='''指定氧化层厚度。'''
        self.t_TSI=tcadparameter('TSI','Real','','m')
        self.t_TSI.description='''Specifies the silicon thickness.'''
        self.t_TSI.description_zh='''指定硅片的厚度。'''
        self.t_VDRAIN=tcadparameter('VDRAIN','Real','','V')
        self.t_VDRAIN.description='''Specifies the drain voltage used when the data in CVFILE and IVFILE were created.'''
        self.t_VDRAIN.description_zh='''指定创建 CVFILE 和 IVFILE 数据时使用的漏极电压。'''
        self.t_WIDTH=tcadparameter('WIDTH','Real','','m')
        self.t_WIDTH.description='''Specifies the width of the device.'''
        self.t_WIDTH.description_zh='''指定设备的宽度。'''
        self.parameters=['t_ACCEPTOR','t_CVFILE','t_DONOR','t_EG300','t_EI','t_EMAX','t_GRAIN_SIZE','t_GRAINFILE','t_INTFILE','t_IVFILE','t_LENGTH','t_MIN_DENSITY','t_MU','t_NUM_DIVISIONS','t_NUM_GRAINS','t_OUTFILE','t_TEMPERATURE','t_TOX','t_TSI','t_VDRAIN','t_WIDTH']
class c_ELECTRODE (tcadcommand):
    def __init__(self):
        self.commandname='ELECTRODE'
        self.t_A_MAX=tcadparameter('A.MAX','Real','','degrees')
        self.t_A_MAX.description='''Specifies the maximum angle of a 3D cylindrical electrode.'''
        self.t_A_MAX.description_zh='''指定3D圆柱形电极的最大角度。'''
        self.t_A_MIN=tcadparameter('A.MIN','Real','','degrees')
        self.t_A_MIN.description='''Specifies the minimum angle of a 3D cylindrical electrode.'''
        self.t_A_MIN.description_zh='''指定3D圆柱形电极的最小角度。'''
        self.t_BOTTOM=tcadparameter('BOTTOM','Logical','False','')
        self.t_FLOATING=tcadparameter('FLOATING','Logical','False','')
        self.t_FLOATING.description='''Marks an enclosed electrode as a floating semiconductor region. See Section 3.5.10
“Floating Semiconductor Regions”.'''
        self.t_FLOATING.description_zh='''将封闭电极标记为浮置半导体区域。参见第3.5.10节“浮置半导体区域”。'''
        self.t_HELMHOLTZ=tcadparameter('HELMHOLTZ','Logical','True','')
        self.t_HELMHOLTZ.description='''If  set  to  False,  this  excludes  the  corresponding  region  from  the  solution  of  the
Helmholtz equation. This is commonly used to prevent Atlas from solving Helmholtz
equation inside an electrode that overlaps with an otherwise rectangular grid defining
the solution domain.'''
        self.t_HELMHOLTZ.description_zh='''如果设置为False，这将排除相应的区域，使其不被包含在求解赫尔姆霍兹方程的解中。这通常用于防止Atlas在与其他矩形求解域定义重叠的电极内部求解赫尔姆霍兹方程。'''
        self.t_IX_HIGH=tcadparameter('IX.HIGH','Integer','right side of structure','')
        self.t_IX_HIGH.description='''Specifies the maximum x-value of the grid index. The alias for this parameter is
IX.MAX.'''
        self.t_IX_HIGH.description_zh='''指定网格索引的最大x值。此参数的别名是IX.MAX。'''
        self.t_IX_LOW=tcadparameter('IX.LOW','Integer','left side of structure','')
        self.t_IX_LOW.description='''Specifies the minimum x-value of the grid index. The alias for this parameter is
IX.MIN'''
        self.t_IX_LOW.description_zh='''指定网格索引的最小x值。此参数的别名是
IX.MIN'''
        self.t_IX_MAX=tcadparameter('IX.MAX','Integer','right side of structure','')
        self.t_IX_MIN=tcadparameter('IX.MIN','Integer','left side of structure','')
        self.t_IY_MAX=tcadparameter('IY.MAX','Integer','bottom side of structure','')
        self.t_IY_MIN=tcadparameter('IY.MIN','Integer','top side of structure','')
        self.t_IY_HIGH=tcadparameter('IY.HIGH','Integer','bottom of structure','')
        self.t_IY_HIGH.description='''Specifies the maximum y-value of the grid index. The alias for this parameter is
IY.MAX.'''
        self.t_IY_HIGH.description_zh='''指定网格索引的最大y值。此参数的别名是IY.MAX。'''
        self.t_IY_LOW=tcadparameter('IY.LOW','Integer','top of structure','')
        self.t_IY_LOW.description='''Specifies the minimum y-value of the grid index. The alias for this parameter is
IX.MIN. Nodes, which have x and y grid indices, between IX.LOW and IX.HIGH
and  between  IY.LOW  and  IY.HIGH  are  designated  electrode  nodes.  Normally,
horizontal planar electrodes will be used. In this case, IY.LOW equals IY.HIGH.'''
        self.t_IY_LOW.description_zh='''指定网格索引的最小y值。此参数的别名是IX.MIN。x和y网格索引在IX.LOW和IX.HIGH之间以及IY.LOW和IY.HIGH之间的节点被指定为电极节点。通常，将使用水平平面电极。在这种情况下，IY.LOW等于IY.HIGH。'''
        self.t_IZ_MAX=tcadparameter('IZ.MAX','Integer','','')
        self.t_IZ_MIN=tcadparameter('IZ.MIN','Integer','','')
        self.t_IZ_HIGH=tcadparameter('IZ.HIGH','Integer','','')
        self.t_IZ_HIGH.description='''Specifies the maximum z-value of the grid index. The alias for this parameter is
IZ.MAX.'''
        self.t_IZ_HIGH.description_zh='''指定网格索引的最大z值。此参数的别名是IZ.MAX。'''
        self.t_IZ_LOW=tcadparameter('IZ.LOW','Integer','','')
        self.t_IZ_LOW.description='''Specifies the minimum z-value of the grid index. The alias for this parameter is
IX.MIN.'''
        self.t_IZ_LOW.description_zh='''指定网格索引的最小z值。此参数的别名是IX.MIN。'''
        self.t_LEFT=tcadparameter('LEFT','Logical','False','')
        self.t_LEFT.description='''Specifies  that  the  electrode  starts  at  the  left-hand  edge  of  the  device. The
electrode will be positioned from left to right along the top of the device.'''
        self.t_LEFT.description_zh='''指定电极从设备的左边缘开始。电极将沿着设备的顶部从左到右定位。'''
        self.t_LENGTH=tcadparameter('LENGTH','Real','length of structure','m')
        self.t_LENGTH.description='''Specifies the length of the electrode in the X direction. It is not necessary to specify
X.MIN, X.MAX, and LENGTH. If two of these parameters are specified, the value of the
third parameter will be calculated.'''
        self.t_LENGTH.description_zh='''指定电极在X方向上的长度。不需要指定X.MIN、X.MAX和LENGTH。如果指定了其中两个参数，第三个参数的值将会被计算出来。'''
        self.t_MATERIAL=tcadparameter('MATERIAL','Character','Contact','')
        self.t_MATERIAL.description='''Specifies a material for the electrode (see Table B-1). This material will be displayed
in TonyPlot. The electrode material can also be used to define the electrode thermal
characteristics  (thermal  conductivity)  and  optical  characteristics  (complex  index  of
refraction).  Setting  the  material  here  does  not  apply  any  electrical  property  such  as
workfunction  to  the  terminal. All  electrical  properties  of  electrodes  are  set  on  the
CONTACT statement.'''
        self.t_MATERIAL.description_zh='''指定电极材料（见表B-1）。该材料将在TonyPlot中显示。电极材料还可用于定义电极的热特性（热导率）和光学特性（折射率的复数指数）。在这里设置材料不会将任何电气属性（如功函数）应用于端子。电极的所有电气属性都在CONTACT语句中设置。'''
        self.t_MODIFY=tcadparameter('MODIFY','Logical','False','')
        self.t_MODIFY.description='''To mark an electrode read from a Standard Structure File as a floating semiconductor
region  specify  both  MODIFY  and  FLOATING  flags.  See  Section  3.5.10  “Floating
Semiconductor Regions”.'''
        self.t_MODIFY.description_zh='''要将从标准结构文件中读取的电极标记为浮置半导体区域，请同时指定MODIFY和FLOATING标志。参见第3.5.10节“浮置半导体区域”。'''
        self.t_NAME=tcadparameter('NAME','Character','','')
        self.t_NAME.description='''Specifies  an  electrode  name.  The  electrode  name  can  be  referenced  by  other Atlas
statements  to  modify  characteristics  of  the specified  electrode.  For  reference  by the
CONTACT  or  THERMCONTACT  statements  any  valid  character  string  can  be  used  and
properly  cross-referenced.  But  when  setting  voltages,  currents  and  charge  from  the
SOLVE  statement  certain  electrode  names  are  recognized  in  a  simplified  syntax.  By
prepending  the  electrode  name  with  "V"  for  voltage,  "I"  for  current  and  "Q"  for
charge,  you  can  directly  and  conveniently  set  the  electrode  bias,  current  or  charge
respectively.  For example:
SOLVE VGATE=1.0 
can  be  used 
to  assign  1  volt  bias 
to 
the  electrode  named  "GATE".  In  such  a
manner,  the  following  list  of  names  can  be  used  to  set  voltage,  current  or  charge:
GATE, FGATE, CGATE, NGATE, PGATE, and VGG.
The  following  list  of  names  can  be  used  to  assign  only  voltage  or  current:  DRAIN,
SOURCE,  BULK,  SUBSTRATE,  EMITTER,  COLLECTOR,  BASE,  ANODE,  CATHODE,
WELL,  NWELL,  PWELL,  CHANNEL,  GROUND,  NSOURCE,  PSOURCE,  NDRAIN,
PDRAIN, VDD, VSS, VEE, and VBBVCC.'''
        self.t_NAME.description_zh='''指定一个电极名称。该电极名称可以被其他Atlas语句引用，以修改指定电极的特性。对于CONTACT或THERMCONTACT语句的引用，可以使用任何有效的字符字符串，并且可以正确地交叉引用。但在从SOLVE语句设置电压、电流和电荷时，某些电极名称在简化的语法中被识别。通过在电极名称前加上“V”表示电压、“I”表示电流和“Q”表示电荷，你可以直接且方便地设置电极偏压、电流或电荷。例如：

SOLVE VGATE=1.0
可以用作将1伏偏压分配给名为“GATE”的电极。以这种方式，以下名称列表可以用来设置电压、电流或电荷：

GATE、FGATE、CGATE、NGATE、PGATE和VGG。

以下名称列表可以用来仅分配电压或电流：DRAIN、SOURCE、BULK、SUBSTRATE、EMITTER、COLLECTOR、BASE、ANODE、CATHODE、WELL、NWELL、PWELL、CHANNEL、GROUND、NSOURCE、PSOURCE、NDRAIN、PDRAIN、VDD、VSS、VEE和VBBVCC。'''
        self.t_NUMBER=tcadparameter('NUMBER','Integer','defined #(electrodes)+ 1','')
        self.t_NUMBER.description='''Specifies an electrode number from 1 to 50. Electrode numbers may be specified in
any order. If  NUMBER is not specified, electrodes will be automatically numbered in
sequential order. This parameter cannot re-number electrodes already defined in Atlas
or other programs.'''
        self.t_NUMBER.description_zh='''指定从1到50的电极编号。电极编号可以以任意顺序指定。如果未指定编号，电极将自动按顺序编号。此参数无法重新编号在Atlas或其他程序中已经定义的电极。'''
        self.t_R_MAX=tcadparameter('R.MAX','Real','','m')
        self.t_R_MAX.description='''Specifies the maximum radius of a 3D cylindrical electrode.'''
        self.t_R_MAX.description_zh='''指定三维圆柱形电极的最大半径。'''
        self.t_R_MIN=tcadparameter('R.MIN','Real','','m')
        self.t_R_MIN.description='''Specifies the minimum radius of a 3D cylindrical electrode.'''
        self.t_R_MIN.description_zh='''指定3D圆柱形电极的最小半径。'''
        self.t_RIGHT=tcadparameter('RIGHT','Logical','False','')
        self.t_RIGHT.description='''Specifies that the electrode starts at the right-hand edge of the device. The
electrode will be positioned from right to left along the top of the device.'''
        self.t_RIGHT.description_zh='''指定电极从设备的右侧边缘开始。电极将沿设备顶部从右向左定位。'''
        self.t_SUBSTRATE=tcadparameter('SUBSTRATE','Logical','False','')
        self.t_SUBSTRATE.description='''Places 
the 
specified 
electrode 
at 
the  bottom  of 
the  device 
and  names 
the
electrode, substrate.'''
        self.t_SUBSTRATE.description_zh='''将指定的电极放置在设备的底部，并将该电极命名为基片。'''
        self.t_THERMAL=tcadparameter('THERMAL','Logical','False','')
        self.t_THERMAL.description='''Specifies 
that 
the  electrode 
is 
treated  as  a  boundary  condition 
for  heatflow
simulation using Giga.'''
        self.t_THERMAL.description_zh='''指定
电极
作为
热量流动
模拟
的边界条件
使用Giga。'''
        self.t_TOP=tcadparameter('TOP','Logical','False','')
        self.t_TOP.description='''Specifies that the electrode is positioned along the top of the device.'''
        self.t_TOP.description_zh='''指定电极沿着设备的顶部位置。'''
        self.t_X_MAX=tcadparameter('X.MAX','Real','right side of structure','m')
        self.t_X_MAX.description='''Specifies the maximum x-boundary of the electrode.'''
        self.t_X_MAX.description_zh='''指定电极的最大x边界。'''
        self.t_X_MIN=tcadparameter('X.MIN','Real','left side of structure','m')
        self.t_X_MIN.description='''Specifies the minimum x-boundary of the electrode.'''
        self.t_X_MIN.description_zh='''指定电极的最低x边界。'''
        self.t_Y_MAX=tcadparameter('Y.MAX','Real','Y.MIN','m')
        self.t_Y_MAX.description='''Specifies the maximum y-boundary of the electrode.'''
        self.t_Y_MAX.description_zh='''指定电极的最大y边界。'''
        self.t_Y_MIN=tcadparameter('Y.MIN','Real','top of the structure','m')
        self.t_Y_MIN.description='''Specifies the minimum y-boundary of the electrode.'''
        self.t_Y_MIN.description_zh='''指定电极的最低y边界。'''
        self.t_Z_MIN=tcadparameter('Z.MIN','Real','','m')
        self.t_Z_MIN.description='''Specifies the minimum z-boundary of the electrode.'''
        self.t_Z_MIN.description_zh='''指定电极的最小z边界。'''
        self.t_Z_MAX=tcadparameter('Z.MAX','Real','','m')
        self.t_Z_MAX.description='''Specifies the maximum z-boundary of the electrode.'''
        self.t_Z_MAX.description_zh='''指定电极的最大z轴边界。'''
        self.parameters=['t_A_MAX','t_A_MIN','t_BOTTOM','t_FLOATING','t_HELMHOLTZ','t_IX_HIGH','t_IX_LOW','t_IX_MAX','t_IX_MIN','t_IY_MAX','t_IY_MIN','t_IY_HIGH','t_IY_LOW','t_IZ_MAX','t_IZ_MIN','t_IZ_HIGH','t_IZ_LOW','t_LEFT','t_LENGTH','t_MATERIAL','t_MODIFY','t_NAME','t_NUMBER','t_R_MAX','t_R_MIN','t_RIGHT','t_SUBSTRATE','t_THERMAL','t_TOP','t_X_MAX','t_X_MIN','t_Y_MAX','t_Y_MIN','t_Z_MIN','t_Z_MAX']
