        self.t_EGD.description_zh='''指定与施主态相对应的高斯分布峰的能量。此能量是从价带边缘测量的。'''
        self.t_EP_AMPHOTERIC=tcadparameter('EP.AMPHOTERIC','Real','1.27','eV')
        self.t_EP_AMPHOTERIC.description='''Specifies the most probable potential defect energy.'''
        self.t_EP_AMPHOTERIC.description_zh='''指定最可能的潜在缺陷能量。'''
        self.t_EU_AMPHOTERIC=tcadparameter('EU.AMPHOTERIC','Real','0.2','eV')
        self.t_EU_AMPHOTERIC.description='''Specifies the defect electron correlation energy.'''
        self.t_EU_AMPHOTERIC.description_zh='''指定缺陷电子相关能。'''
        self.t_EV0_AMPHOTERIC=tcadparameter('EV0.AMPHOTERIC','Real','0.056','eV')
        self.t_EV0_AMPHOTERIC.description='''Specifies the characteristic energy.'''
        self.t_EV0_AMPHOTERIC.description_zh='''指定特征能量。'''
        self.t_F_INTDEFECTS=tcadparameter('F.INTDEFECTS','Character','','')
