        self.t_FILEY_AMPHOTERIC.description_zh='''指定在 FILE.AMPHOTERIC 中使用的 Y 坐标。'''
        self.t_FILEZ_AMPHOTERIC=tcadparameter('FILEZ.AMPHOTERIC','Character','','')
