class c_INTTRAP (tcadcommand):
    def __init__(self):
        self.commandname='INTTRAP'
        self.t_ACCEPTOR=tcadparameter('ACCEPTOR','Logical','False','')
        self.t_ACCEPTOR.description='''Specifies an acceptor-type trap level.'''
        self.t_ACCEPTOR.description_zh='''指定一个接受器类型的陷阱等级。'''
        self.t_DEGEN_FAC=tcadparameter('DEGEN.FAC','Real','1','')
        self.t_DEGEN_FAC.description='''Specifies the degeneracy factor of the trap level used to calculate the density.'''
        self.t_DEGEN_FAC.description_zh='''指定用于计算密度的陷阱能级的简并因子。'''
        self.t_DENSITY=tcadparameter('DENSITY','Real','','cm-2')
        self.t_DENSITY.description='''Sets the maximum density of states of the trap level.'''
        self.t_DENSITY.description_zh='''设置陷阱能级状态的最大密度。'''
        self.t_DEPTH=tcadparameter('DEPTH','Real','5.0e-3','m')
        self.t_DEPTH.description='''The depth that the uniform interface trap density penetrates into the insulator. This
requires the HEIMAN model.'''
        self.t_DEPTH.description_zh='''均匀界面陷阱密度穿透到绝缘体内部的深度。这需要使用HEIMAN模型。'''
        self.t_DEVICE=tcadparameter('DEVICE','Character','','')
        self.t_DEVICE.description='''Specifies  which  device  the  statement  applies  to  in  MixedMode  simulation.  The
synonym for this parameter is STRUCTURE.'''
        self.t_DEVICE.description_zh='''指定在混合模式仿真中该语句适用于哪个设备。此参数的同义词是STRUCTURE。'''
        self.t_DONOR=tcadparameter('DONOR','Logical','False','')
        self.t_DONOR.description='''Specifies a donor-type trap level.'''
        self.t_DONOR.description_zh='''指定一个捐赠型陷阱级别。'''
        self.t_E_LEVEL=tcadparameter('E.LEVEL','Real','','eV')
        self.t_E_LEVEL.description='''Sets the energy of the discrete trap level. It is equal to the energy distance between
conductance band and trap level for acceptor trap, and to energy distance between
trap level and valence band for donor trap.'''
        self.t_E_LEVEL.description_zh='''设置离散陷阱能级。对于受主陷阱，它等于导带与陷阱能级之间的能量距离，而对于施主陷阱，它等于陷阱能级与价带之间的能量距离。'''
        self.t_E0N=tcadparameter('E0N','Real','','s-1')
        self.t_E0N.description='''Specifies the trap emission rate for elections.'''
        self.t_E0N.description_zh='''指定选举中的陷阱排放率。'''
        self.t_E0P=tcadparameter('E0P','Real','','s-1')
        self.t_E0P.description='''Specifies the trap emission rate for holes.'''
        self.t_E0P.description_zh='''指定陷阱发射率，用于空穴。'''
        self.t_F_E0N=tcadparameter('F.E0N','Real','','s-1')
        self.t_F_E0N.description='''Specifies the name of a file containing a C-Interpreter function describing the trap
emission rate for electrons as a function of time.'''
        self.t_F_E0N.description_zh='''指定一个包含C-解释器函数的文件名，该函数描述了随时间变化的电子陷阱发射率。'''
        self.t_F_E0P=tcadparameter('F.E0P','Real','','s-1')
        self.t_F_E0P.description='''Specifies the name of a file containing a C-Interpreter function describing the trap
emission rate for holes as a function of time.'''
        self.t_F_E0P.description_zh='''指定一个包含C-解释器函数的文件名，该函数描述了随时间变化的空穴陷阱发射率。'''
        self.t_F_DENSITY=tcadparameter('F.DENSITY','Character','','')
        self.t_F_DENSITY.description='''Specifies  the  name  of  a  file  containing  a  C-Interpreter  function  describing  the
density of donor/acceptor interface traps as a function of position.'''
        self.t_F_DENSITY.description_zh='''指定一个文件名，该文件包含一个C-解释器函数，描述了施主/受体界面陷阱密度随位置变化的函数。'''
        self.t_F_EXTMSCRATES=tcadparameter('F.EXTMSCRATES','Character','','')
        self.t_F_EXTMSCRATES.description='''Specifies the file containing an extended C-Interpreter function for transition rates
in multistate trap model.'''
        self.t_F_EXTMSCRATES.description_zh='''指定包含用于多状态陷阱模型中转移率扩展C解释器函数的文件。'''
        self.t_F_MSCRATES=tcadparameter('F.MSCRATES','Character','','')
        self.t_F_MSCRATES.description='''Specifies  the  file  containing  the  C-Interpreter  function  for  transition
rates in multistate trap model.'''
        self.t_F_MSCRATES.description_zh='''指定包含多状态陷阱模型中转移率计算的C-解释器函数的文件。'''
        self.t_GRA_3_DET=tcadparameter('GRA.3.DET','Logical','False','')
