        self.t_CHIB.description_zh='''指定 Concannon 闸流模型中的电子分布函数常数。'''
        self.t_CHUANG=tcadparameter('CHUANG','Logical','False','')
        self.t_CHUANG.description='''This is an alias for the WZ.KP parameter.'''
        self.t_CHUANG.description_zh='''这是WZ.KP参数的别名。'''
        self.t_CONCDL=tcadparameter('CONCDL','Logical','False','')
        self.t_CONMOB=tcadparameter('CONMOB','Logical','False','')
