        self.t_LMODE.description_zh='''指定在激光仿真期间要考虑多个纵向模型。'''
        self.t_LORENTZ=tcadparameter('LORENTZ','Logical','False','')
        self.t_LORENTZ.description='''Enables Lorentz gain broadening.'''
        self.t_LORENTZ.description_zh='''启用洛伦兹增益展宽。'''
        self.t_LSMMOB=tcadparameter('LSMMOB','Logical','False','')
        self.t_LSMMOB.description='''This is an alias for CVT.'''
        self.t_LSMMOB.description_zh='''这是CVT的别名。'''
