class c_MQW (tcadcommand):
    def __init__(self):
        self.commandname='MQW'
        self.t_ACCEPTORS=tcadparameter('ACCEPTORS','Real','0.0','cm-3')
        self.t_ACCEPTORS.description='''Specifies a uniform density of ionized acceptors in the quantum wells.'''
        self.t_ACCEPTORS.description_zh='''指定量子阱中电离受主均匀密度。'''
        self.t_ALT_SCHRO=tcadparameter('ALT.SCHRO','Logical','False','')
        self.t_ALT_SCHRO.description='''Specifies  that  the  alternative  Schrodinger  solver  should  be  used  in  the
calculations.'''
        self.t_ALT_SCHRO.description_zh='''指定在计算中应使用替代的薛定谔解算器。'''
        self.t_ASTR=tcadparameter('ASTR','Real','0.0','')
        self.t_BSTR=tcadparameter('BSTR','Real','0.0','')
        self.t_CSTR=tcadparameter('CSTR','Real','0.0','')
        self.t_DELTA=tcadparameter('DELTA','Real','0.341','eV')
        self.t_DELTA.description='''Specifies the spin orbital splitting energy in the quantum well.'''
        self.t_DELTA.description_zh='''指定量子阱中的自旋轨道分裂能量。'''
        self.t_DONORS=tcadparameter('DONORS','Real','0.0','cm-3')
        self.t_DONORS.description='''Specifies the uniform density of ionized donors in the quantum wells.'''
        self.t_DONORS.description_zh='''指定量子阱中电离施主的均匀密度。'''
        self.t_DSTR=tcadparameter('DSTR','Real','0.0','')
        self.t_EPSILON=tcadparameter('EPSILON','Real','0.0','')
        self.t_EPSILON.description='''Specifies  the  high  frequency  permittivity  to  used  in  calculating  the  gain
and radiative recombinations.'''
        self.t_EPSILON.description_zh='''指定用于计算增益和辐射复合的高频介电常数。'''
        self.t_ESTR=tcadparameter('ESTR','Real','0.0','')
        self.t_FSTR=tcadparameter('FSTR','Real','0.0','')
        self.t_GAIN0=tcadparameter('GAIN0','Real','1.0','')
        self.t_GAIN0.description='''Scaling factor for the MQW gain models.'''
        self.t_GAIN0.description_zh='''MQW增益模型的缩放因子。'''
        self.t_GAMMA0=tcadparameter('GAMMA0','Real','2.010-3','eV')
        self.t_GAMMA0.description='''Specifies the width in eV (Note: GAMMA0=h/TAU.IN).'''
        self.t_GAMMA0.description_zh='''指定宽度，单位为电子伏特（注意：GAMMA0=h/TAU.IN）。'''
        self.t_GSCALE=tcadparameter('GSCALE','Real','1.0','')
        self.t_GSCALE.description='''Specifies a scale factor to be multiplied by the optical gain.'''
        self.t_GSCALE.description_zh='''指定一个缩放因子，用于乘以光学增益。'''
        self.t_ISHIKAWA=tcadparameter('ISHIKAWA','Logical','False','')
        self.t_ISHIKAWA.description='''Specifies  that  the  Ishikawa  model  [151]  is  used  to  account  for  strain
effects  (see  Section  3.9.12  “Ishikawa's  Strain  Effects  Model”  for  more
information).'''
        self.t_ISHIKAWA.description_zh='''指定使用石川模型[151]来解释应变效应（更多信息请参见第3.9.12节“石川的应变效应模型”）。'''
        self.t_LI=tcadparameter('LI','Logical','False','')
        self.t_LI.description='''Specifies  that  the  Li  model  [54]  be  used  for  spontaneous  emission  in
multiple  quantum  wells. The  DELTA,  MSTAR,  MC  and  MHH  parameters
can be used with this model.'''
        self.t_LI.description_zh='''指定使用Li模型[54]来计算多量子阱中的自发发射。DELTA、MSTAR、MC和MHH参数可以与该模型一起使用。'''
        self.t_LORENTZ=tcadparameter('LORENTZ','Logical','False','')
        self.t_LORENTZ.description='''This  is  the  Lorentzian  line  broadening  model  for  MQW  gain.  The  half
width  of  the  Lorentzian  shape  function  is  controlled  by  the  GAMMA0
parameter 
of 
the  MQW 
statement.  You 
can 
also 
set 
the  TAU.IN
parameter  to  specify  the  intraband  relaxation  time  in  seconds.  For  more
information  about  the  Lorentzian  line  broadening  model,  see  Section
3.9.11 “Lorentzian Gain Broadening”.'''
        self.t_LORENTZ.description_zh='''这是MQW增益的洛伦兹线展宽模型。洛伦兹形状函数的半宽由MQW语句中的GAMMA0参数控制。您还可以设置TAU.IN参数来指定秒内的带内松弛时间。关于洛伦兹线展宽模型的更多信息，请参见第3.9.11节“洛伦兹增益展宽”。'''
        self.t_MATERIAL=tcadparameter('MATERIAL','Character','','')
        self.t_MATERIAL.description='''Specifies  the  name  of  the  material  to  be  used  in  the  wells.  The  barrier
material is taken from whatever material is already in the structure at the
MQW location.'''
        self.t_MATERIAL.description_zh='''指定用于井中的材料名称。屏障材料取自MQW位置结构中已有的任何材料。'''
        self.t_MC=tcadparameter('MC','Real','0.067','')
        self.t_MC.description='''This is the conduction band effective mass.'''
        self.t_MC.description_zh='''这是导带有效质量。'''
        self.t_MHH=tcadparameter('MHH','Real','0.62','')
        self.t_MHH.description='''This is the heavy hole effective mass.'''
        self.t_MHH.description_zh='''这是重空穴有效质量。'''
        self.t_MLH=tcadparameter('MLH','Real','0.087','')
        self.t_MLH.description='''This is the light hole effective mass.'''
        self.t_MLH.description_zh='''这是光子孔有效质量。'''
        self.t_MSTAR=tcadparameter('MSTAR','Real','0.053','')
        self.t_MSTAR.description='''Disperses energy in the conduction band. This doesn’t necessarily equate
to the conduction band effective mass, see [382].'''
        self.t_MSTAR.description_zh='''在导带中分散能量。这并不一定等同于导带有效质量，参见[382]。'''
        self.t_NBS=tcadparameter('NBS','Integer','15','')
        self.t_NBS.description='''Defines  the  number  of  bound  states  used  in  solving  the  Schrodinger
equation.'''
        self.t_NBS.description_zh='''定义了解决薛定谔方程时使用的束缚态数量。'''
        self.t_NWELL=tcadparameter('NWELL','Integer','1','')
        self.t_NWELL.description='''Specifies the number of quantum wells.'''
        self.t_NWELL.description_zh='''指定量子阱的数量。'''
        self.t_NX=tcadparameter('NX','Integer','10','')
        self.t_NY=tcadparameter('NY','Integer','10','')
        self.t_RESOLVE=tcadparameter('RESOLVE','Logical','True','')
        self.t_RESOLVE.description='''Specifies  whether  the  band  edge  discontinuities  at  the  well  edges  are
resolved by the device equations.'''
        self.t_RESOLVE.description_zh='''指定是否通过设备方程解决了位于井边缘的能带边缘不连续性。'''
        self.t_SPONTANEOUS=tcadparameter('SPONTANEOUS','Logical','False','')
        self.t_SPONTANEOUS.description='''Specifies  whether 
the  quantum  well 
spontaneous 
recombination 
is
included in the device continuity equations.'''
        self.t_SPONTANEOUS.description_zh='''指定是否将量子阱自发重组包含在设备连续性方程中。'''
        self.t_STRAIN=tcadparameter('STRAIN','Real','0.0','')
        self.t_STRAIN.description='''Specifies the strain percentage in the quantum well.'''
        self.t_STRAIN.description_zh='''指定量子阱中的应变百分比。'''
        self.t_STABLE=tcadparameter('STABLE','Integer','0','')
        self.t_STABLE.description='''Specifies 
the 
table  row 
to  be  used  for  coefficients 
to  calculate 
the
effective masses in strained quantum wells.'''
        self.t_STABLE.description_zh='''指定用于计算应变量子阱中有效质量的系数所使用的表格行。'''
        self.t_SY=tcadparameter('SY','Real','','m')
        self.t_SY.description='''Specifies  the  maximum  mesh  spacing  to  be  applied  in  the Y  direction
through the quantum wells.'''
