        self.t_SIGAH.description_zh='''指定受主陷阱的孔捕获截面积。'''
        self.t_SIGDE=tcadparameter('SIGDE','Real','1.010-14','cm2')
        self.t_SIGDE.description='''Specifies the electron capture cross-section for donor traps.'''
        self.t_SIGDE.description_zh='''指定施主陷阱的电子捕获截面。'''
        self.t_SIGDH=tcadparameter('SIGDH','Real','1.010-16','cm2')
