        self.t_SIGMAA.description_zh='''指定了受主型陷阱掺杂分布的高斯宽度。'''
        self.t_SIGMAD=tcadparameter('SIGMAD','Real','0','eV')
        self.t_SIGMAD.description='''Specifies the Gaussian width for the donor-like traps dopant distribution.'''
        self.t_SIGMAD.description_zh='''指定施主型陷阱掺杂分布的高斯宽度。'''
        self.t_SIGMAIA=tcadparameter('SIGMAIA','Real','0','eV')
        self.t_SIGMAIA.description='''Specifies the Gaussian width for the acceptor-like traps intrinsic distribution.'''
        self.t_SIGMAIA.description_zh='''指定受主型陷阱本征分布的高斯宽度。'''
        self.t_SIGMAID=tcadparameter('SIGMAID','Real','0','eV')
        self.t_SIGMAID.description='''Specifies the Gaussian width for the donor-like traps intrinsic distribution.'''
        self.t_SIGMAID.description_zh='''指定类施主陷阱固有分布的高斯宽度。'''
        self.t_STRUCTURE=tcadparameter('STRUCTURE','Character','','')
