class c_QTREGION (tcadcommand):
    def __init__(self):
        self.commandname='QTREGION'
        self.t_DEVICE=tcadparameter('DEVICE','Character','','')
        self.t_DEVICE.description='''Specifies  which  device  the  statement  applies  in  the  mixed  mode  simulation. The
synonym for this parameter is STRUCTURE.'''
        self.t_DEVICE.description_zh='''指定在混合模式仿真中该语句适用于哪个设备。这个参数的同义词是STRUCTURE。'''
        self.t_F_RESOLUTION=tcadparameter('F.RESOLUTION','Character','','')
        self.t_F_RESOLUTION.description='''Specifies  a  text  file  that  contains  a  column  of  numbers  between  0  and  1.  This
determines  the  mesh  spacing  in  the  tunneling  direction  and  is  an  alternative  to
PTS.TUNNEL. The numbers give the mesh points relative to the corners, 0.0 maps
to the starting corner, and 1.0 maps to the ending corner. Intermediate mesh points
are calculated according to a linear  mapping from the supplied coordinates in [0,1].'''
        self.t_F_RESOLUTION.description_zh='''指定一个文本文件，其中包含一列介于0和1之间的数字。这决定了隧道方向上的网格间距，作为PTS.TUNNEL的替代方案。这些数字给出了相对于角落的网格点，0.0映射到起始角落，1.0映射到结束角落。中间的网格点根据从[0,1]提供的坐标的线性映射来计算。'''
        self.t_NUMBER=tcadparameter('NUMBER','Real','1','')
        self.t_NUMBER.description='''This is the index of the polygonal region that the QTREGION statement applies to.'''
        self.t_NUMBER.description_zh='''这是QTREGION语句所适用的多边形区域的索引。'''
        self.t_PTS_NORMAL=tcadparameter('PTS.NORMAL','Real','-1','')
        self.t_PTS_NORMAL.description='''This 
is 
the  number  of  points 
in  quadrilateral 
in  direction  perpendicular 
to
tunneling  direction.  This  dictates  a  regular  mesh  spacing  along  the  sides  from
corner 1 to corner 2 and from corner 3 to  corner 4. See Figure 3-9 for an example.'''
        self.t_PTS_NORMAL.description_zh='''这是四边形内垂直于隧道方向的点的数量。这决定了从角1到角2以及从角3到角4的侧面规则网格间距。具体示例见图3-9。'''
        self.t_PTS_TUNNEL=tcadparameter('PTS.TUNNEL','Real','-1','')
        self.t_PTS_TUNNEL.description='''This  is  the  number  of  points  in  quadrilateral  in  direction  parallel  to  tunneling
direction.   This  dictates  a  regular  mesh  spacing  along  the  sides  from  corner  1  to
corner 4 and from corner 2 to corner 3.'''
        self.t_PTS_TUNNEL.description_zh='''这是在平行于隧道挖掘方向的四边形中的点数。这决定了从角1到角4以及从角2到角3的边上的规则网格间距。'''
        self.t_SNRM_BEG=tcadparameter('SNRM.BEG','Real','0','m')
        self.t_SNRM_BEG.description='''Along with SNRM.END, is one way of specifying the mesh spacing in the direction
normal  to  tunneling.  SNRM.BEG  specifies  the  mesh  spacing  at  the  corner  1  (4).
SNRM.END specifies it at the corner 2 (3).'''
        self.t_SNRM_BEG.description_zh='''与SNRM.END一起，是用来指定沿隧道法向网格间距的一种方式。SNRM.BEG指定在角点1（4）的网格间距。SNRM.END指定在角点2（3）的网格间距。'''
        self.t_SNRM_END=tcadparameter('SNRM.END','Real','0','m')
        self.t_SNRM_END.description='''See SNRM.BEG.'''
        self.t_SNRM_END.description_zh='''请参见SNRM.BEG。'''
        self.t_STNL_BEG=tcadparameter('STNL.BEG','Real','0','m')
        self.t_STNL_BEG.description='''Along with STNL.END, is one way of specifying the mesh spacing in the direction
parallel  to  tunneling.  STNL.BEG  specifies  the  mesh  spacing  at  the  corner  1  (2).
STNL.END specifies it at the corner 4 (3).'''
        self.t_STNL_BEG.description_zh='''与STNL.END一起，是确定与隧道平行方向的网格间距的一种方式。STNL.BEG指定了角落1（2）处的网格间距。STNL.END指定了角落4（3）处的网格间距。'''
        self.t_STNL_END=tcadparameter('STNL.END','Real','0','m')
        self.t_STNL_END.description='''See STNL.BEG.'''
        self.t_STNL_END.description_zh='''查看STNL.BEG。'''
        self.t_STRUCTURE=tcadparameter('STRUCTURE','Character','','')
        self.t_STRUCTURE.description='''This is a synonym for DEVICE.'''
        self.t_STRUCTURE.description_zh='''这是DEVICE的同义词。'''
        self.t_X1=tcadparameter('X1','Real','0','m')
        self.t_X1.description='''This is the X coordinate of the first corner of the quadrilateral.'''
        self.t_X1.description_zh='''这是四边形第一个角的X坐标。'''
        self.t_X2=tcadparameter('X2','Real','0','m')
        self.t_X2.description='''This is the X coordinate of the second corner of the quadrilateral.'''
        self.t_X2.description_zh='''这是四边形第二个角的X坐标。'''
        self.t_X3=tcadparameter('X3','Real','0','m')
        self.t_X3.description='''This is the X coordinate of the third corner of the quadrilateral.'''
        self.t_X3.description_zh='''这是四边形第三个角的X坐标。'''
        self.t_X4=tcadparameter('X4','Real','0','m')
        self.t_X4.description='''This is the X coordinate of the fourth corner of the quadrilateral.'''
        self.t_X4.description_zh='''这是四边形第四个角的X坐标。'''
        self.t_Y1=tcadparameter('Y1','Real','0','m')
        self.t_Y1.description='''This is the Y coordinate of the first  corner of the quadrilateral.'''
        self.t_Y1.description_zh='''这是四边形第一个角的Y坐标。'''
        self.t_Y2=tcadparameter('Y2','Real','0','m')
        self.t_Y2.description='''This is the Y coordinate of the second corner of the quadrilateral.'''
        self.t_Y2.description_zh='''这是四边形第二个角的Y坐标。'''
        self.t_Y3=tcadparameter('Y3','Real','0','m')
        self.t_Y3.description='''This is the Y coordinate of the third  corner of the quadrilateral.'''
        self.t_Y3.description_zh='''这是四边形第三个角的Y坐标。'''
        self.t_Y4=tcadparameter('Y4','Real','0','m')
        self.t_Y4.description='''This is the Y coordinate of the fourth corner of the quadrilateral.'''
        self.t_Y4.description_zh='''这是四边形第四个角的Y坐标。'''
        self.parameters=['t_DEVICE','t_F_RESOLUTION','t_NUMBER','t_PTS_NORMAL','t_PTS_TUNNEL','t_SNRM_BEG','t_SNRM_END','t_STNL_BEG','t_STNL_END','t_STRUCTURE','t_X1','t_X2','t_X3','t_X4','t_Y1','t_Y2','t_Y3','t_Y4']
class c_COMM (tcadcommand):
    def __init__(self):
        self.commandname='COMM'
        self.parameters=['']
class c_QTX_M (tcadcommand):
    def __init__(self):
        self.commandname='QTX.M'
        self.t_LOCATION=tcadparameter('LOCATION','Real','','m')
        self.t_LOCATION.description='''Specifies the location of the grid line.'''
        self.t_LOCATION.description_zh='''指定网格线的位置。'''
        self.t_NODE=tcadparameter('NODE','Integer','','')
        self.t_NODE.description='''Specifies the mesh line index. These mesh lines are assigned consecutively.'''
        self.t_NODE.description_zh='''指定网格线索引。这些网格线按顺序分配。'''
        self.t_SPACING=tcadparameter('SPACING','Real','','m')
        self.t_SPACING.description='''Specifies  the  mesh  spacing  at  the  mesh  locations  specified  by  the  LOCATION
parameter.  If  the  SPACING  parameter  is  specified,  then  the  NODE  parameter
should not be specified.'''
        self.t_SPACING.description_zh='''指定由LOCATION参数指定的网格位置处的网格间距。如果指定了SPACING参数，那么不应指定NODE参数。'''
        self.parameters=['t_LOCATION','t_NODE','t_SPACING']
class c_QUIT (tcadcommand):
    def __init__(self):
        self.commandname='QUIT'
        self.parameters=['']
class c_REACTION (tcadcommand):
    def __init__(self):
        self.commandname='REACTION'
        self.t_AFTER_N=tcadparameter('AFTER.N','Integer','0','')
        self.t_AFTER_N.description='''Number of electrons produced by reaction.'''
        self.t_AFTER_N.description_zh='''反应产生的电子数量。'''
        self.t_AFTER_P=tcadparameter('AFTER.P','Integer','0','')
        self.t_AFTER_P.description='''Number of holes produced by reaction.'''
        self.t_AFTER_P.description_zh='''反应产生的孔洞数量。'''
        self.t_AFTER_SP1=tcadparameter('AFTER.SP1','Integer','0','')
        self.t_AFTER_SP1.description='''Number of SPECIES1 ions produced by reaction.'''
        self.t_AFTER_SP1.description_zh='''反应产生的SPECIES1离子的数量。'''
        self.t_AFTER_SP2=tcadparameter('AFTER.SP2','Integer','0','')
        self.t_AFTER_SP2.description='''Number of SPECIES2 ions produced by reaction.'''
        self.t_AFTER_SP2.description_zh='''反应产生的SPECIES2离子的数量。'''
        self.t_AFTER_SP3=tcadparameter('AFTER.SP3','Integer','0','')
        self.t_AFTER_SP3.description='''Number of SPECIES3 ions produced by reaction.'''
        self.t_AFTER_SP3.description_zh='''反应产生的SPECIES3离子的数量。'''
        self.t_BEFORE_N=tcadparameter('BEFORE.N','Integer','0','')
        self.t_BEFORE_N.description='''Number of electrons consumed by reaction.'''
        self.t_BEFORE_N.description_zh='''反应消耗的电子数。'''
        self.t_BEFORE_P=tcadparameter('BEFORE.P','Integer','0','')
        self.t_BEFORE_P.description='''Number of holes consumed by reaction.'''
        self.t_BEFORE_P.description_zh='''反应消耗的孔数。'''
        self.t_BEFORE_SP1=tcadparameter('BEFORE.SP1','Integer','0','')
        self.t_BEFORE_SP1.description='''Number of SPECIES1 ions consumed by reaction.'''
        self.t_BEFORE_SP1.description_zh='''反应消耗的SPECIES1离子数量。'''
        self.t_BEFORE_SP2=tcadparameter('BEFORE.SP2','Integer','0','')
        self.t_BEFORE_SP2.description='''Number of SPECIES2 ions consumed by reaction.'''
        self.t_BEFORE_SP2.description_zh='''反应消耗的SPECIES2离子数量。'''
        self.t_BEFORE_SP3=tcadparameter('BEFORE.SP3','Integer','0','')
        self.t_BEFORE_SP3.description='''Number of SPECIES3 ions consumed by reaction.'''
        self.t_BEFORE_SP3.description_zh='''反应消耗的SPECIES3离子数量。'''
        self.t_EQUIRATE=tcadparameter('EQUIRATE','Real','0.0','cm-3s-1')
        self.t_EQUIRATE.description='''Fixed reaction rate in cm-3s-1.'''
        self.t_EQUIRATE.description_zh='''固定的反应速率，单位为cm^-3s^-1。'''
        self.t_FORWARD_EA=tcadparameter('FORWARD.EA','Real','0.0','eV')
        self.t_FORWARD_EA.description='''Activation energy in eV of forward reaction rate.'''
        self.t_FORWARD_EA.description_zh='''前向反应速率的激活能量，单位为电子伏特(eV)。'''
        self.t_FORWARD_RATE=tcadparameter('FORWARD.RATE','Real','0.0','See description')
        self.t_FORWARD_RATE.description='''Forward reaction rate constant.  The forward rate itself  can depend on any
product  of  concentrations,  and  the  rate  constant  should  give  overall  rate
dimensions of cm-3s-1.'''
        self.t_FORWARD_RATE.description_zh='''前向反应速率常数。前向速率本身可以依赖于任何浓度的乘积，速率常数应该给出总体的速率单位，为cm^-3s^-1。'''
        self.t_REVERSE_EA=tcadparameter('REVERSE.EA','Real','0.0','eV')
        self.t_REVERSE_EA.description='''Activation energy in eV of reverse reaction rate.'''
        self.t_REVERSE_EA.description_zh='''反向反应速率的激活能，单位为电子伏特(eV)。'''
        self.t_REVERSE_RATE=tcadparameter('REVERSE.RATE','Real','0.0','See description')
        self.t_REVERSE_RATE.description='''Reverse reaction rate constant.   The reverse rate itself  can depend on  any
product  of  concentrations,  and  the  rate  constant  should  give  overall  rate
dimensions of cm-3s-1.'''
        self.t_REVERSE_RATE.description_zh='''逆向反应速率常数。逆向反应速率本身可以依赖于任何浓度的乘积，而且速率常数应给出总体的速率维度，单位为cm^-3s^-1。'''
        self.parameters=['t_AFTER_N','t_AFTER_P','t_AFTER_SP1','t_AFTER_SP2','t_AFTER_SP3','t_BEFORE_N','t_BEFORE_P','t_BEFORE_SP1','t_BEFORE_SP2','t_BEFORE_SP3','t_EQUIRATE','t_FORWARD_EA','t_FORWARD_RATE','t_REVERSE_EA','t_REVERSE_RATE']
class c_REGION (tcadcommand):
    def __init__(self):
        self.commandname='REGION'
        self.t_ABS=tcadparameter('ABS','Logical','False','')
        self.t_ABS.description='''Specifies 
that 
quantum 
confinement 
is 
included 
in 
the 
calculation 
of
absorption  or  imaginary  index  of  refraction. To  use  this  model,  you  must  also
specify  QWELL  on  the  REGION  statement.  See  Section  11.8.3  “Quantum  Well
Absorption”.'''
        self.t_ABS.description_zh='''指定量子限制效应包含在吸收或折射率的虚部的计算中。要使用此模型，您还必须在REGION语句中指定QWELL。参见第11.8.3节“量子阱吸收”。'''
        self.t_A_MAX=tcadparameter('A.MAX','Real','','degrees')
        self.t_A_MAX.description='''Specifies the maximum angle of a 3D cylindrical region.'''
        self.t_A_MAX.description_zh='''指定3D圆柱区域的 最大角度。'''
        self.t_A_MIN=tcadparameter('A.MIN','Real','','degress')
        self.t_A_MIN.description='''Specifies the minimum angle of a 3D cylindrical region.'''
        self.t_A_MIN.description_zh='''指定3D圆柱区域的最小角度。'''
        self.t_A_SILICO=tcadparameter('A-SILICO','Logical','False','')
        self.t_ACCEPTORS=tcadparameter('ACCEPTORS','Real','0.0','cm-3')
        self.t_ACCEPTORS.description='''Specifies a uniform density of ionized acceptors in the region.'''
        self.t_ACCEPTORS.description_zh='''指定该区域内电离受主的均匀密度。'''
        self.t_ALGAAS=tcadparameter('ALGAAS','Logical','False','')
        self.t_ALINAS=tcadparameter('ALINAS','Logical','False','')
        self.t_ASUB=tcadparameter('ASUB','Real','1.0','Å')
        self.t_ASUB.description='''Specifies  the  substrate  lattice  constant  for  strain  calculations  as  described  in
Section 3.6.11 “Epitaxial Strain Tensor Calculation in Wurtzite”.'''
        self.t_ASUB.description_zh='''指定用于计算应变量的衬底晶格常数，如第3.6.11节“闪锌矿结构中的外延应变张量计算”所述。'''
        self.t_AXIAL=tcadparameter('AXIAL','Real','0.0','')
        self.t_AXIAL.description='''Specifies the axial strain zz in a region.'''
        self.t_AXIAL.description_zh='''指定一个区域中的轴向应变zz。'''
        self.t_BOTTOM=tcadparameter('BOTTOM','Logical','False','')
        self.t_BOTTOM.description='''Specifies 
that  the  region 
is 
to  be  added  at  the  bottom  (starting  at  the
maximum previously specified Y coordinate and extending in the positive Y
direction) of the structure.'''
        self.t_BOTTOM.description_zh='''指定该区域将被添加到结构的底部（从之前指定的最大Y坐标开始，并向正Y方向延伸）。'''
        self.t_CALC_STRAIN=tcadparameter('CALC.STRAIN','Logical','False','')
        self.t_CALC_STRAIN.description='''Specifies that the strain in the region is calculated from the lattice mismatch with
adjacent regions.'''
        self.t_CALC_STRAIN.description_zh='''指定该区域的应变是通过与相邻区域的晶格不匹配来计算的。'''
        self.t_COMPX_BOTTOM=tcadparameter('COMPX.BOTTOM','Real','0.0','')
        self.t_COMPY_BOTTOM=tcadparameter('COMPY.BOTTOM','Real','0.0','')
        self.t_COMPX_TOP=tcadparameter('COMPX.TOP','Real','0.0','')
        self.t_COMPY_TOP=tcadparameter('COMPY.TOP','Real','0.0','')
        self.t_CONDUCTOR=tcadparameter('CONDUCTOR','Logical','False','')
        self.t_CONDUCTOR.description='''Specifies that the region is to be simulated as a conductor. This means that the
conduction equation is solved for the region.'''
        self.t_CONDUCTOR.description_zh='''指定该区域模拟为导体。这意味着该区域的传导方程被求解。'''
        self.t_CONVERT=tcadparameter('CONVERT','Logical','False','')
        self.t_CONVERT.description='''This is an alias for MODIFY.'''
        self.t_CONVERT.description_zh='''这是MODIFY的一个别名。'''
        self.t_DEC_C1=tcadparameter('DEC.C1','Real','0.0','eV')
        self.t_DEC_C1.description='''This is a conduction band shift for 1st pair of electron valleys.'''
        self.t_DEC_C1.description_zh='''这是第一对电子谷的导带移动。'''
        self.t_DEC_C2=tcadparameter('DEC.C2','Real','0.0','eV')
        self.t_DEC_C2.description='''This is a conduction band shift for 2nd pair of electron valleys.'''
        self.t_DEC_C2.description_zh='''这是第二对电子谷的导带移动。'''
        self.t_DEC_C3=tcadparameter('DEC.C3','Real','0.0','eV')
