class c_DBR (tcadcommand):
    def __init__(self):
        self.commandname='DBR'
        self.t_BOTTOM=tcadparameter('BOTTOM','Logical','False','')
        self.t_BOTTOM.description='''Specifies that the DBR is to be added at the bottom (starting at
the maximum previously specified Y coordinate and extending
in the positive Y direction) of the structure.'''
        self.t_BOTTOM.description_zh='''指定将DBR添加到结构的底部（从先前指定的最大Y坐标开始，并向正Y方向延伸）。'''
        self.t_CALC1_STRAIN=tcadparameter('CALC1.STRAIN','Logical','False','')
        self.t_CALC2_STRAIN=tcadparameter('CALC2.STRAIN','Logical','False','')
        self.t_HALF_CYCLES=tcadparameter('HALF.CYCLES','Real','2','')
        self.t_HALF_CYCLES.description='''Specifies the total number of layers. Note that if HALF.CYCLES
is odd, there will be more layers of one material than the other.
Its alias is LAYERS.'''
        self.t_HALF_CYCLES.description_zh='''指定总层数。注意如果HALF.CYCLES是奇数，一种材料的层数会比另一种多。它的别名为LAYERS。'''
        self.t_LAYERS=tcadparameter('LAYERS','Real','2','')
        self.t_LAYERS.description='''This is an alias for HALF.CYCLES.'''
        self.t_LAYERS.description_zh='''这是HALF.CYCLES的别名。'''
        self.t_LED1=tcadparameter('LED1','Logical','False','')
        self.t_LED2=tcadparameter('LED2','Logical','False','')
        self.t_MAT1=tcadparameter('MAT1','Character','','')
        self.t_MAT1.description='''Specifies the material name for layers of material 1.'''
        self.t_MAT1.description_zh='''指定材料1的层的材料名称。'''
        self.t_MAT2=tcadparameter('MAT2','Character','','')
        self.t_MAT2.description='''Specifies the material name for layers of material 2.'''
        self.t_MAT2.description_zh='''指定材料2层的材料名称。'''
        self.t_N1=tcadparameter('N1','Real','0','')
        self.t_N1.description='''Specifies the integer number of mesh lines per layer of material 1. Note that if
N1 is specified, then SPA1 shouldn’t be specified.'''
        self.t_N1.description_zh='''指定材料1每层的网格线整数数量。注意，如果指定了N1，那么不应指定SPA1。'''
        self.t_N2=tcadparameter('N2','Real','0','')
        self.t_N2.description='''Specifies the integer number of mesh lines per layer of material 2. Note that if
N2 is specified, then SPA2 shouldn’t be specified.'''
        self.t_N2.description_zh='''指定材料2每层的网格线整数数量。请注意，如果指定了N2，那么不应指定SPA2。'''
        self.t_NA1=tcadparameter('NA1','Real','0.0','cm-3')
        self.t_NA1.description='''Specifies the ionized acceptor concentration in layers of material 1.'''
        self.t_NA1.description_zh='''指定材料1层中的电离受主浓度。'''
        self.t_NA2=tcadparameter('NA2','Real','0.0','cm-3')
        self.t_NA2.description='''Specifies the ionized acceptor concentration in layers of material 2.'''
        self.t_NA2.description_zh='''指定材料2层中的电离受主浓度。'''
        self.t_NAME1=tcadparameter('NAME1','Character','','')
        self.t_NAME2=tcadparameter('NAME2','Character','','')
        self.t_ND1=tcadparameter('ND1','Real','0.0','cm-3')
        self.t_ND1.description='''Specifies the ionized donor concentration in layers of material 1.'''
        self.t_ND1.description_zh='''指定材料1层中的电离施主浓度。'''
        self.t_ND2=tcadparameter('ND2','Real','0.0','cm-3')
        self.t_ND2.description='''Specifies the ionized donor concentration in layers of material 2.'''
        self.t_ND2.description_zh='''指定材料2层中的电离施主浓度。'''
        self.t_NU12=tcadparameter('NU12','Integer','5','')
        self.t_NU12.description='''This is the number of grid lines in the graded region between the 1st and 2nd
half cycle in the direction specified by the BOTTOM or TOP parameters.'''
        self.t_NU12.description_zh='''这是在由BOTTOM或TOP参数指定的方向上，第1个和第2个半周期之间分级区域中网格线的数量。'''
        self.t_NU21=tcadparameter('NU21','Integer','5','')
        self.t_NU21.description='''This is the number of grid lines in the graded region between the 2nd and 1st
half cycle in the direction specified by the BOTTOM or TOP parameters.'''
        self.t_NU21.description_zh='''这是在由BOTTOM或TOP参数指定的方向上，第2个和第1个半周期之间分级区域中的网格线数量。'''
        self.t_POLARIZ1=tcadparameter('POLARIZ1','Logical','False','')
        self.t_POLARIZ2=tcadparameter('POLARIZ2','Logical','False','')
        self.t_POLAR1_CHARG=tcadparameter('POLAR1.CHARG','Real','0','cm-2')
        self.t_POLAR2_CHARG=tcadparameter('POLAR2.CHARG','Real','0','cm-2')
        self.t_POLAR1_SCALE=tcadparameter('POLAR1.SCALE','Real','1.0','')
        self.t_POLAR2_SCALE=tcadparameter('POLAR2.SCALE','Real','1.0','')
        self.t_QWELL1=tcadparameter('QWELL1','Logical','False','')
        self.t_QWELL2=tcadparameter('QWELL2','Logical','False','')
        self.t_SPA1=tcadparameter('SPA1','Real','0.0','m')
        self.t_SPA1.description='''Specifies the spacing between mesh lines in layers of material 1. Note that this
should be smaller than or equal to THICK1.'''
        self.t_SPA1.description_zh='''指定材料1层中网格线之间的间距。请注意，这应小于或等于THICK1。'''
        self.t_SPA2=tcadparameter('SPA2','Real','0.0','m')
        self.t_SPA2.description='''Specifies the spacing between mesh lines in layers of material 2. Note that this
should be smaller than or equal to THICK2.'''
        self.t_SPA2.description_zh='''指定材料层2中网格线之间的间距。注意，这应该小于或等于THICK2。'''
        self.t_STRAIN1=tcadparameter('STRAIN1','Real','0.0','')
        self.t_STRAIN1.description='''Specifies 
the 
strain 
in 
the 
layer 
of  material 
1. 
(Negative 
strain 
is
compressive).'''
        self.t_STRAIN1.description_zh='''指定材料1层的应变。（负应变表示压缩。）'''
        self.t_STRAIN2=tcadparameter('STRAIN2','Real','0.0','')
        self.t_STRAIN2.description='''Specifies 
the 
strain 
in 
the 
layer 
of  material 
2. 
(Negative 
strain 
is
compressive).'''
        self.t_STRAIN2.description_zh='''指定材料层中的应变。（负应变表示压缩。）'''
        self.t_TH12=tcadparameter('TH12','Real','','')
        self.t_TH12.description='''This is the thickness of grading region between 1st half cycle and 2nd half cycle
going in the direction specified by the BOTTOM or TOP parameters.'''
        self.t_TH12.description_zh='''这是由第一个半周期和第二个半周期之间的分级区域厚度，沿着BOTTOM或TOP参数指定的方向。'''
        self.t_TH21=tcadparameter('TH21','Real','','')
        self.t_TH21.description='''This is the thickness of grading region between 2nd half cycle and 1st half cycle
going in the direction specified by the BOTTOM or TOP parameters.'''
        self.t_TH21.description_zh='''这是第二半周期和第一半周期之间分级区域的厚度，沿着由BOTTOM或TOP参数指定的方向。'''
        self.t_THICK1=tcadparameter('THICK1','Real','0.0','m')
        self.t_THICK1.description='''Specifies the thickness of each layer of material 1.'''
        self.t_THICK1.description_zh='''指定每层材料1的厚度。'''
        self.t_THICK2=tcadparameter('THICK2','Real','0.0','m')
        self.t_THICK2.description='''Specifies the thickness of each layer of material 2.'''
        self.t_THICK2.description_zh='''指定每层材料的厚度 2。'''
        self.t_TOP=tcadparameter('TOP','Logical','False','')
        self.t_TOP.description='''Specifies  that  the  DBR  is  to  be  added  at  the  top  (starting  at  the  minimum
previously specified Y coordinate and extending in the negative Y direction) of
the structure.'''
        self.t_TOP.description_zh='''指定DBR位于结构的顶部（从先前指定的最小Y坐标开始并向负Y方向延伸）。'''
        self.t_WELL1_CNBS=tcadparameter('WELL1.CNBS','Integer','1','')
        self.t_WELL2_CNBS=tcadparameter('WELL2.CNBS','Integer','1','')
        self.t_WELL1_FIELD=tcadparameter('WELL1.FIELD','Logical','True','')
        self.t_WELL2_FIELD=tcadparameter('WELL2.FIELD','Logical','True','')
        self.t_WELL1_GAIN=tcadparameter('WELL1.GAIN','Real','1.0','')
        self.t_WELL2_GAIN=tcadparameter('WELL2.GAIN','Real','1.0','')
        self.t_WELL1_NX=tcadparameter('WELL1.NX','Integer','10','')
        self.t_WELL2_NX=tcadparameter('WELL2.NX','Integer','10','')
        self.t_WELL1_NY=tcadparameter('WELL1.NY','Integer','10','')
        self.t_WELL2_NY=tcadparameter('WELL2.NY','Integer','10','')
        self.t_WELL1_VNBS=tcadparameter('WELL1.VNBS','Integer','1','')
        self.t_WELL2_VNBS=tcadparameter('WELL2.VNBS','Integer','1','')
        self.t_X1_COMP=tcadparameter('X1.COMP','Real','0.0','')
        self.t_X1_COMP.description='''Specifies the composition fraction x in layers of material 1.'''
        self.t_X1_COMP.description_zh='''指定材料1层中的组分分数x。'''
        self.t_X2_COMP=tcadparameter('X2.COMP','Real','0.0','')
        self.t_X2_COMP.description='''Specifies the composition fraction x in layers of material 2.'''
